package com.networkmonitorpro.ui; import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.*;import androidx.lifecycle.*;import com.networkmonitorpro.R;import com.networkmonitorpro.network.NetworkSnapshot;import com.networkmonitorpro.ui.viewmodel.MainViewModel; public class DashboardFragment extends Fragment{ public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.fragment_dashboard,c,false);} public void onViewCreated(View v,Bundle b){MainViewModel m=new ViewModelProvider(requireActivity()).get(MainViewModel.class); TextView type=v.findViewById(R.id.networkType), details=v.findViewById(R.id.details); ProgressBar sig=v.findViewById(R.id.signalMeter); SpeedGraphView graph=v.findViewById(R.id.speedGraph); m.detector.snapshots.observe(getViewLifecycleOwner(),s->{type.setText(s.type);sig.setProgress(s.signalLevel);graph.add(s.downBps);details.setText("Signal: "+s.signalLevel+"%\nQuality: "+s.qualityScore+"/100\nDownload: "+fmt(s.downBps)+"\nUpload: "+fmt(s.upBps)+"\nCarrier: "+s.carrier+"\nSIM: "+s.simStatus+"\nInternet: "+(s.reachable?"Reachable":"Unavailable"));});} private String fmt(long b){return b/1000000.0+" Mbps";} }
